#include <iostream>
#include <cmath>
#include <iomanip>

using namespace Eigen;

int main() {
    // Test case
    double x1 = 0.0, y1 = 0.0, z1 = 0.0;
    double x2 = 2.0, y2 = 0.0, z2 = 0.0;
    double x3 = 1.0, y3 = 1.5, z3 = 0.0;
    double E_mod = 2.1e11;
    double nu = 0.3;
    double t = 0.01;

    // Build E matrix (3x2): columns are i-vector and j-vector
    // E(1),E(3),E(5) = i-vector; E(2),E(4),E(6) = j-vector
    // Stored column-major in Fortran: E(1..3)=col1, E(4..6)=col2
    Vector3d ivec, jvec, kvec;

    ivec(0) = x2 - x1;
    ivec(1) = y2 - y1;
    ivec(2) = z2 - z1;

    double XSUBB = ivec.norm();
    ivec /= XSUBB;

    Vector3d rsubc;
    rsubc(0) = x3 - x1;
    rsubc(1) = y3 - y1;
    rsubc(2) = z3 - z1;

    double XSUBC = ivec.dot(rsubc);

    kvec = ivec.cross(rsubc);
    double YSUBC = kvec.norm();
    kvec /= YSUBC;

    jvec = kvec.cross(ivec);
    jvec.normalize();

    double VOL = XSUBB * YSUBC * t / 2.0;
    double REELMU = 1.0 / XSUBB;
    double FLAMDA = 1.0 / YSUBC;
    double DELTA = XSUBC / XSUBB - 1.0;

    // C matrix (3x6), stored by rows in Fortran C(1..18)
    // CSUBA = C(1..6), CSUBB = C(7..12), CSUBC = C(13..18)
    MatrixXd C(3, 6);
    C(0,0) = -REELMU;  C(0,1) = 0.0;
    C(1,0) = 0.0;      C(1,1) = FLAMDA*DELTA;
    C(2,0) = C(1,1);   C(2,1) = -REELMU;

    C(0,2) = REELMU;   C(0,3) = 0.0;
    C(1,2) = 0.0;      C(1,3) = -FLAMDA*REELMU*XSUBC;
    C(2,2) = C(1,3);   C(2,3) = REELMU;

    C(0,4) = 0.0;      C(0,5) = 0.0;
    C(1,4) = 0.0;      C(1,5) = FLAMDA;
    C(2,4) = FLAMDA;   C(2,5) = 0.0;

    // Material matrix G (3x3) for plane stress
    // G11 = E/(1-nu^2), G12 = nu*E/(1-nu^2), G22 = same as G11, G33 = G = E/(2(1+nu))
    double G11 = E_mod / (1.0 - nu*nu);
    double G12 = nu * G11;
    double G22 = G11;
    double G33 = E_mod / (2.0 * (1.0 + nu));

    Matrix3d G;
    G << G11, G12, 0.0,
         G12, G22, 0.0,
         0.0, 0.0, G33;

    // E matrix (3x2)
    MatrixXd Emat(3, 2);
    Emat.col(0) = ivec;
    Emat.col(1) = jvec;

    // K = VOL * E * C^T * G * C * E^T
    // E*C^T is (3x2)*(2x6) = (3x6)
    MatrixXd ECt = Emat * C.transpose();  // (3x6)
    MatrixXd ECtG = ECt.transpose() * G;  // (6x3)
    MatrixXd K = VOL * ECtG * C * Emat.transpose();  // (6x6)

    // Print as JSON
    std::cout << std::setprecision(6) << std::scientific;
    std::cout << "{\"stiffness_matrix\":[";
    for (int i = 0; i < 6; i++) {
        std::cout << "[";
        for (int j = 0; j < 6; j++) {
            std::cout << K(i,j);
            if (j < 5) std::cout << ",";
        }
        std::cout << "]";
        if (i < 5) std::cout << ",";
    }
    std::cout << "]}" << std::endl;

    return 0;
}
